package dailyassignments;

public class Program_ASCIICode {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        char alpha1='A';
        int num1=alpha1;
        System.out.println("ASCII value of A="+num1);
        
        char alpha2='a';
        int num2=alpha2;
        System.out.println("ASCII value of a="+num2);
        
        char alpha3='0';
        int num3=alpha3;
        System.out.println("ASCII value of 0="+num3);
        
        char alpha4='@';
        int num4=alpha4;
        System.out.println("ASCII value of @="+num4);
	}

}
